from fractions import Fraction


def expected_turns(n: int, m: int, jumps: list[list[int]]) -> list[int] | None:
    jump_to = dict(jumps)
    destination = [-1 if cell in jump_to else cell for cell in range(n + 1)]

    for start in jump_to:
        path = []
        cell = start
        while destination[cell] == -1:
            path.append(cell)
            cell = jump_to[cell]
        for cell in path:
            destination[cell] = destination[path[-1]] if False else destination[cell]
        end = start
        # Resolve this chain to its final cell.
        while end in jump_to:
            end = jump_to[end]
        for cell in path:
            destination[cell] = end

    transitions = {}
    reverse = [[] for _ in range(n + 1)]
    reachable = {0}
    stack = [0]

    while stack:
        cell = stack.pop()
        if cell == n:
            continue

        counts = {}
        for roll in range(1, m + 1):
            landing = cell + roll
            if landing > n:
                landing = 2 * n - landing
            target = destination[landing]
            counts[target] = counts.get(target, 0) + 1

        transitions[cell] = counts
        for target in counts:
            reverse[target].append(cell)
            if target not in reachable:
                reachable.add(target)
                stack.append(target)

    can_finish = {n}
    stack = [n]
    while stack:
        for predecessor in reverse[stack.pop()]:
            if predecessor not in can_finish:
                can_finish.add(predecessor)
                stack.append(predecessor)

    if not reachable.issubset(can_finish):
        return None

    states = sorted(reachable - {n})
    index = {cell: i for i, cell in enumerate(states)}
    size = len(states)
    matrix = [[0] * (size + 1) for _ in range(size)]

    for cell, i in index.items():
        matrix[i][i] = m
        matrix[i][size] = m
        for target, count in transitions[cell].items():
            if target != n:
                matrix[i][index[target]] -= count

    # Bareiss elimination keeps every matrix entry integral.
    previous_pivot = 1
    for k in range(size - 1):
        pivot = matrix[k][k]
        pivot_row = matrix[k]
        for i in range(k + 1, size):
            row = matrix[i]
            factor = row[k]
            for j in range(k + 1, size + 1):
                row[j] = (
                    row[j] * pivot - factor * pivot_row[j]
                ) // previous_pivot
            row[k] = 0
        previous_pivot = pivot

    solution = [Fraction(0) for _ in range(size)]
    for i in range(size - 1, -1, -1):
        value = Fraction(matrix[i][size])
        for j in range(i + 1, size):
            value -= matrix[i][j] * solution[j]
        solution[i] = value / matrix[i][i]

    answer = solution[index[0]]
    return [answer.numerator, answer.denominator]
